<script setup lang="ts">
import { Head, useForm } from '@inertiajs/vue3'
defineProps<{broadcasts:{data:any[];total:number}}>()
const form=useForm({message:'',audience:'all',activity_category:'active',recipient_text:'',recipients:[] as string[],throttle_ms:500,max_retries:3,confirmed:false})
const preview=()=>form.message.trim()
const submit=()=>{form.recipients=form.audience==='selected'?form.recipient_text.split(/\r?\n/).map(x=>x.trim()).filter(Boolean):[];form.post('/broadcasts')}
</script>
<template><Head title="ارسال پیام"/><v-container fluid class="pa-6"><h1 class="text-h4 mb-5">ارسال پیام همگانی</h1><v-row><v-col cols="12" md="5"><v-card rounded="xl" class="pa-5"><v-card-title>پیام جدید</v-card-title><v-form @submit.prevent="submit"><v-textarea v-model="form.message" label="متن پیام" counter="4000" rows="5"/><v-select v-model="form.audience" label="مخاطبان" :items="[{title:'همه کاربران',value:'all'},{title:'بر اساس دسته فعالیت',value:'category'},{title:'کاربران انتخابی / یک کاربر',value:'selected'}]"/><v-select v-if="form.audience==='category'" v-model="form.activity_category" label="دسته فعالیت" :items="['heavy_active','active','low_active','dormant','suspicious']"/><v-textarea v-if="form.audience==='selected'" v-model="form.recipient_text" label="شناسه کاربران (هر شناسه در یک خط)" rows="3"/><v-text-field v-model.number="form.throttle_ms" type="number" label="فاصله ارسال (میلی‌ثانیه)"/><v-text-field v-model.number="form.max_retries" type="number" label="حداکثر تلاش مجدد"/><v-card variant="tonal" class="pa-3 mb-3"><div class="text-caption">پیش‌نمایش پیام</div>{{ preview() }}</v-card><v-checkbox v-model="form.confirmed" label="متن و فهرست مخاطبان را بررسی کردم و ارسال را تأیید می‌کنم."/><v-btn type="submit" color="primary" block :disabled="!form.confirmed||!form.message.trim()" :loading="form.processing">قرار دادن در صف ارسال</v-btn></v-form></v-card></v-col><v-col cols="12" md="7"><v-card rounded="xl" class="pa-5"><v-card-title>تاریخچه ارسال</v-card-title><v-list><v-list-item v-for="b in broadcasts.data" :key="b.id" :title="'ارسال #'+b.id" :subtitle="b.message" :href="'/broadcasts/'+b.id"><template #append><v-chip>{{ b.status }} · {{ b.sent }}/{{ b.total }}</v-chip></template></v-list-item></v-list></v-card></v-col></v-row></v-container></template>
